// Packs the library into the tool (packages/cli/data/), which is how it reaches a project: the
// tool carries the components, so there is nothing to host.
//
//   catalog.json              every spec, tokens, icons, guides, the stylesheet, and the needs
//                             table of the skill (which component for what)
//   <framework>.json          the files a project of that framework gets, as they sit in its ui
//                             folder: <name>/<file> for each component (its adapters, recipe and
//                             logic, and an index.ts that exports the adapters) and lib/<file>;
//                             with what each file imports (other files, npm packages), and the
//                             component of every exported name
//   <framework>-examples.json the example files of each component
//   skill/                    the agent skill `fndn init` writes into a project
//
// A component is its index and everything that imports, followed to the end. The build fails if
// an import does not resolve, so what the tool writes into a project always compiles.
import fs from "node:fs";
import path from "node:path";
import { ROOT, COMPONENTS, LIB, read, readJson, exists, loadSpecs, sortSpecs, adapterFiles, adapterSources, exportLines, targetsOf, FRAMEWORKS } from "./lib.mjs";
import { exportTable } from "../packages/cli/src/imports.js";

const OUT = path.join(ROOT, "packages/cli/data");
const CSS = ["index.css", "tokens.css", "tailwind.css", "base.css", "config.css"];
/* The guides the tool serves (`fndn docs <id>`): the design language, the three rule books, how a
 * component is built, and how one is ported to another framework. */
const GUIDES = [
  ["design", "docs/DESIGN.md"],
  ["motion", "docs/design/motion.md"],
  ["interaction", "docs/design/interaction.md"],
  ["accessibility", "docs/design/accessibility.md"],
  /* its last section is about working in this repository */
  ["authoring", "docs/authoring.md", (md) => md.replace(/\n## \d+\. In the library's repository[\s\S]*$/, "\n")],
  ["porting", "docs/porting.md"],
];
/* the framework itself is the project's; it is never something a component asks to install */
const RUNTIME = new Set(["react", "react-dom", "vue", "svelte"]);

/* a file in a project belongs to the project: drop this repository's "GENERATED … do not edit" */
const owned = (code) => code
  .replace(/^(?:\/\/ GENERATED by scripts\/[^\n]*\n|\/\* GENERATED by scripts\/[^\n]*?\*\/\n)+/, "")
  .replace(/^\/\* GENERATED by scripts\/[^\n]*?— do not edit\.\s*/, "/* ");

const specs = sortSpecs(loadSpecs()).map(({ raw }) => raw);
const version = readJson("packages/cli/package.json").version;
const ls = (rel) => fs.readdirSync(path.join(ROOT, rel)).sort();

fs.rmSync(OUT, { recursive: true, force: true });
fs.mkdirSync(OUT, { recursive: true });
const write = (file, value) => fs.writeFileSync(path.join(OUT, file), JSON.stringify(value));

/* ── catalog ──────────────────────────────────────────────────────────────────────────────── */
const guides = GUIDES.map(([id, file, edit = (md) => md]) => {
  const markdown = edit(read(file));
  return { id, title: markdown.match(/^#{1,3}\s+(.+)$/m)?.[1]?.trim() ?? id, markdown };
});

/* "Which component for what": written once, in the skill; `search` answers from the same rows */
const table = read("skill/fndn/SKILL.md").split("### Which component for what")[1]?.split("\n### ")[0] ?? "";
const needs = table.split("\n").filter((l) => /^\|/.test(l)).slice(2).map((row) => {
  const [need, use] = row.split("|").slice(1, 3).map((c) => c.trim());
  const components = [...use.matchAll(/`([a-z][a-z0-9-]*)`/g)].map((m) => m[1]);
  const unknown = components.filter((n) => !specs.some((s) => s.name === n));
  if (unknown.length) throw new Error(`skill/fndn/SKILL.md, "${need}": no component named ${unknown.join(", ")}`);
  return { need, use, components };
});
if (needs.length < 10) throw new Error("skill/fndn/SKILL.md: the \"Which component for what\" table was not found");

const exampleDir = (name) => `${COMPONENTS}/${name}/examples`;
const exampleIndex = Object.fromEntries(specs.filter((s) => exists(`${exampleDir(s.name)}/index.json`)).map((s) => [s.name, readJson(`${exampleDir(s.name)}/index.json`)]));
write("catalog.json", {
  version,
  components: specs,
  tokens: readJson("spec/tokens.json"),
  icons: readJson("spec/icons.json"),
  guides,
  needs,
  examples: exampleIndex,
  styles: Object.fromEntries(CSS.map((f) => [f, owned(read(`packages/core/css/${f}`))])),
});

/* ── one framework ────────────────────────────────────────────────────────────────────────── */
const RELATIVE = /(?:\bfrom\s+|\bimport\s+|\bimport\(\s*)["'](\.{1,2}\/[^"']+)["']/g;
const BARE = /(?:\bfrom\s+|\bimport\s+|\bimport\(\s*)["']([^"'./][^"']*)["']/g;
const packageOf = (specifier) => (specifier.startsWith("@") ? specifier.split("/").slice(0, 2).join("/") : specifier.split("/")[0]);
const ADAPTER = { react: /\.tsx$/, vue: /\.vue$/, svelte: /\.svelte$/ };

function framework(fw) {
  const mine = specs.filter((s) => targetsOf(s).includes(fw));
  /* path in the project's ui folder → content */
  const sources = {};
  for (const f of ls(LIB).filter((f) => f.endsWith(".ts"))) sources[`lib/${f}`] = owned(read(`${LIB}/${f}`));
  for (const spec of mine) {
    const dir = `${COMPONENTS}/${spec.name}`;
    for (const f of adapterFiles(spec, fw)) if (!exists(`${dir}/${f}`)) throw new Error(`${spec.name}: ${dir}/${f} is missing`);
    /* the recipe and the logic are the same for every framework; the adapters are this one's */
    for (const f of ls(dir)) if ((f.endsWith(".ts") && !f.endsWith(".d.ts")) || ADAPTER[fw].test(f)) sources[`${spec.name}/${f}`] = read(`${dir}/${f}`);
    sources[`${spec.name}/index.ts`] = exportLines(spec, fw, (f) => `./${f}`).join("\n") + "\n";
  }

  const have = new Set(Object.keys(sources));
  const resolve = (from, specifier) => {
    const base = path.posix.join(path.posix.dirname(from), specifier);
    const hit = [base, `${base}.ts`, `${base}.tsx`].find((c) => have.has(c));
    if (!hit) throw new Error(`components/${from}: import "${specifier}" does not resolve`);
    return hit;
  };
  const files = {};
  for (const [name, content] of Object.entries(sources)) {
    files[name] = {
      content,
      imports: [...new Set([...content.matchAll(RELATIVE)].map((m) => resolve(name, m[1])))].sort(),
      npm: [...new Set([...content.matchAll(BARE)].map((m) => packageOf(m[1])).filter((p) => !RUNTIME.has(p)))].sort(),
    };
  }

  const ranges = readJson(`${COMPONENTS}/package.json`).dependencies;
  const used = new Set(Object.values(files).flatMap((f) => f.npm));
  const unknown = [...used].filter((p) => !(p in ranges));
  if (unknown.length) throw new Error(`${fw}: the components import ${unknown.join(", ")}, which ${COMPONENTS}/package.json does not list`);
  write(`${fw}.json`, {
    files,
    /* a component's adapter files: when one of them is written, the whole component is */
    components: Object.fromEntries(mine.map((s) => [s.name, adapterFiles(s, fw).map((f) => `${s.name}/${f}`)])),
    /* every exported name and its component, so the docs show each example with the project's imports */
    exports: exportTable(fw, Object.fromEntries(mine.map((s) => [s.name, adapterSources(s, fw)]))),
    versions: Object.fromEntries([...used].sort().map((p) => [p, ranges[p]])),
  });

  const examples = {};
  for (const name of Object.keys(exampleIndex)) {
    examples[name] = Object.fromEntries(ls(exampleDir(name)).filter((f) => ADAPTER[fw].test(f)).map((f) => [f, read(`${exampleDir(name)}/${f}`)]));
  }
  write(`${fw}-examples.json`, examples);
  return `${fw} ${Object.keys(files).length} files`;
}

const built = FRAMEWORKS.map(framework);
fs.cpSync(path.join(ROOT, "skill/fndn"), path.join(OUT, "skill"), { recursive: true, filter: (src) => !src.includes(`${path.sep}evals`) });

const size = fs.readdirSync(OUT).filter((f) => f.endsWith(".json")).reduce((n, f) => n + fs.statSync(path.join(OUT, f)).size, 0);
console.log(`packages/cli/data: ${specs.length} components, ${guides.length} guides; ${built.join(", ")}; ${(size / 1e6).toFixed(1)} MB`);
